<script setup lang="ts">
import { formatDemoTime } from '~/domain/selectors'
definePageMeta({ layout: 'workspace' })
useHead({ title: 'Wawancara kondisional - UKIN PPG UNJ' })
const u = useUkin(), { error, message, act } = useOperationFeedback()
const rows = computed(() => u.user.value ? u.operations.listInterviews() : [])
const selected = ref(''), reason = ref(''), revision = ref(0)
const form = ref({ scheduledAt: '', url: 'https://meet.demo.invalid/ukin', status: 'scheduled' as 'scheduled' | 'rescheduled' | 'completed' | 'cancelled', notes: '' })
function edit(id: string) { const r = rows.value.find(r => r.attemptId === id)!; selected.value = id; revision.value = r.interview?.revision ?? 0; reason.value = ''; form.value = { scheduledAt: wibInput(r.interview?.scheduledAt ?? u.snapshot.value.data.clockNow), url: r.interview?.url ?? 'https://meet.demo.invalid/ukin', status: r.interview?.status ?? 'scheduled', notes: r.interview?.notes ?? '' } }
function save() { act(() => { u.operations.saveInterview(selected.value, { ...form.value, scheduledAt: fromWib(form.value.scheduledAt) }, revision.value, reason.value); selected.value = '' }, 'Jadwal/status wawancara tersimpan. Ini simulasi, bukan pemesanan konferensi.') }
</script>
<template>
  <div class="operations-page"><header><p class="eyebrow">WAWANCARA KONDISIONAL</p><h1>Ruang klarifikasi, bila diperlukan.</h1><p class="muted">Wawancara mengikuti pengaturan periode dan bukan komponen skor keempat. Tautan demo tidak membuat konferensi nyata.</p></header><p v-if="error" class="op-error" role="alert">{{ error }}</p><p v-if="message" class="op-success" role="status">{{ message }}</p><p v-if="!rows.length" class="op-empty">Tidak ada periode wawancara aktif dalam lingkup akun ini.</p>
    <article v-for="r in rows" :key="r.attemptId" class="op-panel"><div class="op-row"><div><h2>{{ r.participant }}</h2><p class="op-caption">{{ r.periodName }} / Paket v{{ r.evidenceVersion ?? '-' }}</p></div><span class="op-tag">{{ r.interview?.status ?? 'Belum dijadwalkan' }}</span></div><p class="op-caption">{{ r.requiredForRelease ? 'Wajib selesai sebelum publikasi pada periode ini.' : 'Tidak menjadi prasyarat publikasi.' }} Penguji: {{ r.examiners.join(' dan ') || 'Belum ditugaskan' }}.</p><template v-if="r.interview"><strong>{{ formatDemoTime(r.interview.scheduledAt) }}</strong><a v-if="r.interview.status !== 'cancelled'" :href="r.interview.url" target="_blank" rel="noopener noreferrer">Buka tautan eksternal wawancara</a><p class="op-caption">Periksa tujuan tautan sebelum membuka. Domain meet.demo.invalid adalah contoh dan tidak menyediakan konferensi.</p><p v-if="r.interview.notes" class="op-note">Catatan internal: {{ r.interview.notes }}</p><details v-if="r.interview.history.length"><summary>Riwayat jadwal</summary><p v-for="(h, i) in r.interview.history" :key="i" class="op-caption">{{ formatDemoTime(h.at) }} / {{ h.status }} / {{ h.reason }}</p></details></template><UButton v-if="u.user.value?.role === 'pengelola'" variant="soft" @click="edit(r.attemptId)">Atur jadwal dan status</UButton></article>
    <form v-if="selected && u.user.value?.role === 'pengelola'" class="op-panel" @submit.prevent="save"><h2>Jadwal {{ rows.find(r => r.attemptId === selected)?.participant }}</h2><div class="op-grid"><label class="op-field">Waktu wawancara (WIB)<input v-model="form.scheduledAt" type="datetime-local" required /></label><label class="op-field">Status<select v-model="form.status"><option value="scheduled">Dijadwalkan</option><option value="rescheduled">Dijadwalkan ulang</option><option value="completed">Selesai</option><option value="cancelled">Dibatalkan</option></select></label></div><label class="op-field">Tautan HTTPS / contoh simulasi<input v-model="form.url" type="url" required /></label><label class="op-field">Catatan internal pengelola dan penguji<textarea v-model="form.notes" maxlength="5000" /></label><label class="op-field">Alasan perubahan<textarea v-model="reason" required maxlength="5000" /></label><div class="op-actions"><UButton type="submit">Simpan jadwal/status</UButton><UButton color="neutral" variant="outline" @click="selected = ''">Batal</UButton></div></form>
  </div>
</template>
